import {SKILLS,AREAS,RUBRIC,KEY,uid,words,escapeHTML as e,freshState,suggestSkills,coverage,extractExperiences,nextGap,gapQuestion,question,storyFromConversation,validateStory,draftStory,scoreAnswer,interviewQuestions,findThread,cvDraft,validateState,deleteStory,sampleState,band,persistState} from './core.js';

const app=document.querySelector('#app'), modal=document.querySelector('#modal');
let state=freshState(), raw=null, storageError='', demo=false, view='home';
let talk=null, interview=null, studio={storyId:'',format:'interview',text:''}, search='', filter='', showScores=false, aiAvailable=false, aiConsent=false;
try {raw=localStorage.getItem(KEY);if(raw)state=validateState(JSON.parse(raw));}catch(err){storageError='Your saved data could not be read. It has not been overwritten. Export a recovery copy in Settings before resetting.';}
function icon(name,extra='') {
  const paths={book:'<path d="M3 4h7a2 2 0 0 1 2 2v15a3 3 0 0 0-3-2H3zM21 4h-7a2 2 0 0 0-2 2v15a3 3 0 0 1 3-2h6z"/>',home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',chat:'<path d="M21 11a8 8 0 0 1-8 8H8l-5 3V11a9 9 0 0 1 18 0Z"/><path d="M8 10h8M8 14h5"/>',cards:'<rect x="5" y="6" width="15" height="15" rx="2"/><path d="M16 3H4a1 1 0 0 0-1 1v12M9 11h7M9 15h4"/>',pen:'<path d="m15 4 5 5M4 20l5-1L21 7a2 2 0 0 0-5-5L4 14z"/>',mic:'<rect x="9" y="2" width="6" height="13" rx="3"/><path d="M5 10v2a7 7 0 0 0 14 0v-2M12 19v3M8 22h8"/>',chart:'<path d="M4 3v18h17M8 16v-5M13 16V7M18 16V4"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3M12 14v3"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',plus:'<path d="M12 4v16M4 12h16"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5ZM20 2v4M18 4h4"/>',check:'<path d="m5 12 4 4L19 6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="m9 3-1 3-3 1-2 3 2 2-1 3 2 3 3-1 3 3 3-2 3 1 2-3-1-3 2-3-3-2-1-3-3 1z"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',volume:'<path d="m11 4-6 5H2v6h3l6 5zM15 8a6 6 0 0 1 0 8M18 5a10 10 0 0 1 0 14"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',leaf:'<path d="M20 3C9 2 3 8 5 16c8 3 15-3 15-13ZM4 21 15 10"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>'};
  return `<svg class="icon ${extra}" viewBox="0 0 24 24" aria-hidden="true">${paths[name]||paths.book}</svg>`;
}
const nav=[['home','home','Your space'],['buddy','chat','Talk to Buddy'],['bank','cards','Story bank'],['studio','pen','Story Studio'],['practice','mic','Practice'],['progress','chart','Your progress']];
const button=(label,action,cls='',extra='')=>`<button class="btn ${cls}" data-action="${action}" ${extra}>${label}</button>`;
function toast(text){const el=document.querySelector('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),5500);}
function save(next) {
  next=validateState({...next,revision:state.revision+1});
  if(!demo){
    if(storageError)throw Error('Saved data needs recovery first. Open Settings.');
    const persisted=persistState(next,localStorage,raw);
    raw=persisted.raw;
    next=persisted.state;
  }
  state=next;
}
function goto(next){location.hash=next;if(view===next)render();}
function openModal(title,body,subtitle='') {
  modal.innerHTML=`<div class="dialog-inner"><div class="dialog-head"><div><h2 id="dialog-title">${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div><button class="round-btn" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button></div>${body}</div>`;
  if(!modal.open)modal.showModal();
}
function pageHead(kicker,title,sub='',action=''){return `<div class="page-head"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1>${sub?`<p class="subhead">${sub}</p>`:''}</div>${action}</div>`;}
function empty(title,text,action=''){return `<div class="empty">${icon('book')}<h3>${title}</h3><p>${text}</p>${action}</div>`;}
function skillGrid(){const counts=coverage(state.stories);return `<div class="skill-grid">${SKILLS.map((s,i)=>`<button class="skill ${counts[s]?'filled':''}" data-action="skill" data-skill="${e(s)}" aria-label="${s}: ${counts[s]} stories">${icon(['chat','cards','spark','leaf','pen','target','book','chart'][i])}<span class="skill-num">${counts[s]||'—'}</span><strong>${s}</strong><span>${counts[s]===1?'1 story':`${counts[s]} stories`}</span></button>`).join('')}</div>`;}
function card(s){return `<article class="story-card"><div class="card-top"><span>${e(s.source||'Your experience')}</span>${icon('book')}</div><h3>${e(s.title)}</h3><p class="excerpt">${e(s.moment)}</p><div class="tags">${s.skills.map(x=>`<span class="tag">${e(x)}</span>`).join('')}</div><div class="card-bottom"><span>${s.omitted?'An almost-overlooked story':'Confirmed by you'}</span><button class="text-link" data-action="story" data-id="${e(s.id)}" aria-label="Open story: ${e(s.title)}">Open ${icon('arrow')}</button></div></article>`;}
function home(){const n=state.stories.length,c=Object.values(coverage(state.stories)).filter(Boolean).length;
  return pageHead('YOUR NEXT CHAPTER',state.profile.name?`Good to see you, ${e(state.profile.name)}.`:'There’s more to your story.','Small moments. Real experiences. A story only you can tell.',button(`${icon('plus')} Find a story`,'start'))+
  `<div class="dashboard-grid"><div><section class="hero"><div class="eyebrow">A LITTLE CURIOSITY GOES A LONG WAY</div><h2>${n?'What have you<br>almost forgotten?':'You don’t need a big<br>achievement to begin.'}</h2><p>${n?'A project, a shift, a moment you stepped in. Let’s find the part that meant something to you.':'The things you do every day say more about you than you think. Buddy will help you find the words.'}</p>${button(`Let’s talk ${icon('arrow')}`,'start','light')}<div class="hero-foot">${icon('lock')} Just a conversation. No right answers.</div>${icon('chat','large')}</section>
  <div class="metrics"><div class="metric">${icon('cards')}<div class="number">${n.toString().padStart(2,'0')}</div><div class="label">Stories collected</div></div><div class="metric">${icon('spark')}<div class="number">${c}<span class="small-muted"> / 8</span></div><div class="label">Skills with a story</div></div><div class="metric">${icon('mic')}<div class="number">${state.attempts.length.toString().padStart(2,'0')}</div><div class="label">Practice answers</div></div></div>
  <div class="section-head"><h2>${n?'Your recent stories':'Your first story starts small'}</h2>${n?'<a href="#bank" class="text-link">View all '+icon('arrow')+'</a>':''}</div>
  ${n?`<div class="story-grid">${state.stories.slice(0,2).map(card).join('')}</div>`:`<div class="panel example"><span class="example-label">A fictional example</span><h2 style="margin:12px 0">“I just helped set up.”</h2><p class="small-muted">Until you remember the two tables with no power. The call you made. The projects that got seen.</p><div class="tags"><span class="tag">Problem solving</span><span class="tag">Initiative</span></div><button class="text-link" data-action="demo">Explore a sample story bank ${icon('arrow')}</button></div>`}</div>
  <aside><section class="panel"><div class="panel-head"><h3>Your skills, taking shape</h3>${icon('spark')}</div>${skillGrid()}<p class="skill-caption">${c?'Every square is backed by your own stories.':'Empty squares are invitations, not grades.'}</p><div class="divider"></div><button class="text-link" data-action="gap">Find a story in a new area ${icon('arrow')}</button></section><section class="thread"><div class="eyebrow">${icon('leaf')} FIND THE THREAD</div><blockquote>${n>=2?'What connects the moments that matter to you?':'One story is a moment.<br>A few reveal a pattern.'}</blockquote><p>Look beyond the achievement. Notice what you care about.</p><button class="text-link" data-action="thread">${n>=2?'Explore your thread':'How it works'} ${icon('arrow')}</button></section></aside></div>
  <section class="below panel"><div class="steps"><div class="step"><span class="step-n">01</span><div><strong>Remember a moment</strong>Buddy asks one question at a time.</div></div><div class="step"><span class="step-n">02</span><div><strong>Make it yours</strong>Check the facts. Keep what matters.</div></div><div class="step"><span class="step-n">03</span><div><strong>Say it out loud</strong>One answer. One fix. Try again.</div></div></section>`;
}
function render(){
  view=location.hash.slice(1)||'home';if(![...nav.map(n=>n[0]),'settings','profile'].includes(view))view='home';
  const screens={home,buddy:buddyView,bank:bankView,studio:studioView,practice:practiceView,progress:progressView,settings:settingsView,profile:profileView};
  app.innerHTML=`${demo?`<div class="demo-banner"><span><strong>Sample space.</strong> These are fictional stories. Changes here are temporary.</span><button class="text-link" data-action="exit-demo">Return to my space ${icon('arrow')}</button></div>`:''}<div class="shell"><aside class="sidebar"><a href="#home" class="brand"><span class="brand-mark">${icon('book')}</span>Your Story</a><div><div class="nav-label">MAKE IT YOURS</div><nav class="nav" aria-label="Main navigation">${nav.map(([id,ic,label])=>`<a href="#${id}" ${id===view?'aria-current="page"':''}>${icon(ic)}${label}</a>`).join('')}</nav></div><div class="sidebar-bottom"><div class="privacy-note">${icon('lock')}<strong>Your words. Your space.</strong>Saved in this browser.<br>Nothing is posted for you.</div><a href="#profile" class="profile-link"><span class="avatar">${e((state.profile.name||'Y')[0].toUpperCase())}</span><span>${e(state.profile.name||'Your profile')}<small>${state.profile.name?'A story in progress':'Make yourself at home'}</small></span></a></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb">Your workspace <span style="margin:0 10px;color:#acb6a6">/</span> ${e(nav.find(n=>n[0]===view)?.[2]|| (view==='profile'?'Profile & CV':'Settings'))}</div><div class="top-actions"><span class="local-badge">${icon('lock')}${demo?'Sample mode':'Private on this device'}</span><a href="#settings" class="round-btn" aria-label="Settings">${icon('settings')}</a></div></header><main id="main" tabindex="-1">${storageError?`<div class="alert error">${e(storageError)} <a href="#settings">Settings</a></div>`:''}${screens[view]()}<footer class="footer-note"><span>Your experiences don’t have to be extraordinary to matter.</span><span>YOUR STORY · ${aiConsent?'AI-assisted session':'Guided, local mode'}</span></footer></main></div></div>`;
  bindForms();
}
function onboarding(){openModal('Let’s start with you.',`<form id="onboard-form"><div class="field"><label for="on-name">What should Buddy call you?</label><input id="on-name" name="name" maxlength="80" required autocomplete="given-name" placeholder="Your first name"></div><div class="field"><label for="on-cv">Got a CV? Paste it here.</label><textarea id="on-cv" name="cv" maxlength="30000" placeholder="Or leave this empty. We can build one together."></textarea><small>You can remove contact information. Everything stays in this browser.</small></div><div class="field"><label for="on-target">Where are you aiming? <span class="muted">Optional</span></label><input id="on-target" name="target" maxlength="300" placeholder="A role, an internship, a new direction…"></div><label class="check"><input type="checkbox" name="confirmed" required><span>I confirm this is my information and want to save it on this device.</span></label><div class="dialog-foot">${button('Save & meet Buddy','submit-onboard','','type="submit"')}</div></form>`,'A little context helps. You can change or delete it whenever you like.');
  document.querySelector('#onboard-form').onsubmit=event=>{event.preventDefault();const data=new FormData(event.target);try{if(!data.get('name').trim())throw Error('Add a name Buddy can use.');save({...state,profile:{...state.profile,name:data.get('name').trim(),cv:data.get('cv').trim(),target:data.get('target').trim(),experiences:[]}});modal.close();goto('buddy');toast('Your space is ready. Choose where to begin.');}catch(err){toast(err.message);}};
}
function buddyView(){
  if(talk){
    const stage=talk.answers.length, step=stage<1?0:stage<4?1:stage<7?2:3;
    return pageHead('TALK TO BUDDY',talk.mode==='gap'?'A different place to look.':'There’s a story in here.','Take your time. Nothing here is saved until you confirm your story.',button('End conversation','end-talk','secondary small'))+
    `<div class="talk-layout"><section class="conversation"><div class="buddy-header"><span class="buddy-icon">${icon('chat')}</span><div><strong>Buddy</strong><small>${aiConsent?'AI selects from open, non-leading questions':'Guided conversation · just between you and this browser'}</small></div></div>
    ${talk.answers.map((a,i)=>`<div class="message"><span class="speaker">Buddy</span>${e(talk.questions[i])}</div><div class="message user"><span class="speaker">You</span>${e(a)}</div>`).join('')}
    ${stage<7?`<div class="message" id="current-question"><span class="speaker">Buddy</span>${e(talk.questions[stage])}</div><div class="row spaced"><button class="text-link" data-action="read-question">${icon('volume')} Read question aloud</button><span class="small-muted">${stage+1} of 7 · ${stage<4?'Finding the moment':'What mattered'}</span></div><form id="talk-form"><div class="field"><label for="talk-answer">In your own words</label><textarea id="talk-answer" name="answer" maxlength="2500" required placeholder="It doesn’t have to sound polished…">${e(talk.draft||'')}</textarea><small>Prefer speaking? Use your keyboard’s dictation microphone. Review the text before continuing.</small></div><div class="actions">${button(`Continue ${icon('arrow')}`,'submit-talk','','type="submit"')}${stage>=5?button('I’m ready to review my story','review-talk','secondary'):''}${stage?button('Change my last answer','back-talk','ghost'):''}</div></form>`:`<div class="panel"><h2>That sounds worth keeping.</h2><p>Read your words together, edit what you need, and confirm what really happened.</p>${button('Review my story','review-talk')}</div>`}</section>
    <aside class="panel" style="align-self:start"><div class="eyebrow">THE CONVERSATION</div><ol class="path">${['Find a starting point','Remember the moment','Understand what mattered','Make it yours'].map((x,i)=>`<li class="${i===step?'active':''}"><span class="n">${i<step?'✓':i+1}</span>${x}</li>`).join('')}</ol><div class="divider"></div><p class="conversation-help">Small is enough. A family responsibility, a difficult shift, a moment you made something easier.</p><p class="conversation-help">You can stop at any time. Buddy isn’t a therapist or a judge.</p></aside></div>`;
  }
  return pageHead('ONE QUESTION AT A TIME','Meet your own experience.','You don’t have to know what the story is yet. Just choose a place to start.')+
    `<div class="mode-grid"><button class="mode-card" data-action="explore">${icon('chat')}<h2>Explore</h2><p>Pick something you’ve done. We’ll look for the moment you almost overlooked.</p><span class="arrow">${icon('arrow')}</span></button><button class="mode-card" data-action="gap">${icon('spark')}<h2>Fill a gap</h2><p>A fresh question to find an experience you haven’t told yet.</p><span class="arrow">${icon('arrow')}</span></button><button class="mode-card" data-action="build-cv">${icon('book')}<h2>Build my CV</h2><p>No CV? No problem. Start with the parts of your life that already hold stories.</p><span class="arrow">${icon('arrow')}</span></button></div>
    <section class="below panel"><div class="two-col"><div><h2>Not “tell me your strengths.”</h2><p class="subhead">More like, “What did you actually do that day?” You bring the memories. Buddy helps you look a little closer.</p></div><div><div class="eyebrow">OUR PROMISE TO YOU</div><ul class="help-list"><li>Questions that leave room for your answer.</li><li>You check the facts before a story is kept.</li><li>Your stories stay yours. No automatic posting.</li></ul></div></div></section>`;
}
function bankView(){
  const shown=state.stories.filter(s=>(!filter||s.skills.includes(filter))&&[s.title,s.moment,s.value,s.source].join(' ').toLowerCase().includes(search.toLowerCase()));
  return pageHead('THE MEMORY BANK','Proof you’ve been doing more.','The moments, decisions and values that make your experience yours.',button(`${icon('plus')} Add a story`,'new-story'))+
    `<div class="filter-bar"><label class="visually-hidden" for="story-search">Search your stories</label><input id="story-search" type="search" placeholder="Search a moment, a value, a memory…" value="${e(search)}"><label class="visually-hidden" for="skill-filter">Filter by skill</label><select id="skill-filter"><option value="">All skills</option>${SKILLS.map(s=>`<option ${filter===s?'selected':''}>${e(s)}</option>`).join('')}</select></div><div id="story-results">${bankResults(shown)}</div><section class="below panel"><div class="section-head"><h2>Your skills, in evidence</h2><button class="text-link" data-action="gap">Explore a gap ${icon('arrow')}</button></div>${skillGrid()}</section>`;
}
function bankResults(shown){return shown.length?`<div class="story-grid">${shown.map(card).join('')}</div>`:empty(state.stories.length?'No stories match yet.':'Your story bank begins with one moment.',state.stories.length?'Try a different word or skill.':'It doesn’t have to sound impressive. It only has to be yours.',button(state.stories.length?'Clear filters':'Talk to Buddy',state.stories.length?'clear-filters':'start','secondary'));}
function storySelect(id,label='Choose a story'){return `<div class="field"><label for="${id}">${label}</label><select id="${id}">${state.stories.map(s=>`<option value="${e(s.id)}" ${s.id===studio.storyId?'selected':''}>${e(s.title)}</option>`).join('')}</select></div>`;}
function studioView(){
  if(!state.stories.length)return pageHead('YOUR WORDS, WITH PURPOSE','Story Studio.')+empty('Start with something real.','Save a story first. Every draft will come from the facts you confirmed.',button('Find a story','start'));
  if(!state.stories.some(s=>s.id===studio.storyId)){studio.storyId=state.stories[0].id;studio.text=draftStory(state.stories[0],studio.format);}
  const s=state.stories.find(s=>s.id===studio.storyId),saved=state.drafts.filter(d=>d.storyId===s.id);
  return pageHead('YOUR WORDS, WITH PURPOSE','A story. A few ways to tell it.','Keep the experience the same. Find the shape that feels like you.')+
    `<div class="two-col"><section class="panel">${storySelect('studio-story')}<div class="eyebrow" style="margin-top:26px">YOUR CONFIRMED FACTS</div>${facts(s)}<div class="tags">${s.skills.map(x=>`<span class="tag">${e(x)}</span>`).join('')}</div><button class="text-link" data-action="edit-story" data-id="${e(s.id)}">Edit the source story ${icon('pen')}</button></section>
    <section class="panel"><div class="tab-buttons" aria-label="Draft format">${[['interview','Interview answer'],['intro','30-second intro'],['linkedin','LinkedIn post']].map(([id,label])=>`<button class="${studio.format===id?'selected':''}" data-action="format" data-format="${id}" aria-pressed="${studio.format===id}">${label}</button>`).join('')}</div><p class="small-muted">${studio.format==='interview'?'Aim for 60–90 seconds, around 130–200 words.':studio.format==='intro'?'Aim for around 30 seconds, around 60–75 words.':'A private draft. Nothing is posted to LinkedIn.'} Short stories stay short; missing facts appear as [add detail].</p><div class="field"><label for="studio-text">Your draft</label><textarea id="studio-text" class="editor" maxlength="20000">${e(studio.text)}</textarea></div><div class="word-count" id="studio-count">${words(studio.text).length} words · ~${Math.round(words(studio.text).length/2.4)} seconds spoken</div><label class="check"><input type="checkbox" id="draft-confirm"><span>I’ve checked this draft. Its factual claims are mine.</span></label><div class="actions">${button('Save draft','save-draft')}${button(`${icon('download')} Download`,'download-draft','secondary')}${button('Copy','copy-draft','secondary')}${button('Practise this story','studio-practice','ghost')}</div>${saved.length?`<div class="divider"></div><h3>Saved versions</h3><div class="saved-list">${saved.map(d=>`<div class="row"><button style="flex:1" data-action="load-draft" data-id="${e(d.id)}">${e(d.format)} · ${new Date(d.createdAt).toLocaleDateString()}</button><button class="round-btn" data-action="delete-draft" data-id="${e(d.id)}" aria-label="Delete saved draft">${icon('close')}</button></div>`).join('')}</div>`:''}</section></div>`;
}
function facts(s){return `<dl class="source-facts">${[['moment','The moment'],['context','A little context'],['action','What I did'],['result','What happened next'],['value','What mattered to me']].map(([k,label])=>`<dt>${label}</dt><dd>${e(s[k]||'Not recorded yet')}</dd>`).join('')}</dl>`;}
function practiceView(){
  if(!state.stories.length)return pageHead('A LITTLE MORE CONFIDENT','Make the words your own.')+empty('Give your answer a real starting point.','Save a story, then practise turning it into an answer you can say out loud.',button('Find a story','start'));
  if(!interview)return pageHead('A LITTLE MORE CONFIDENT','Make the words your own.','One question. One useful fix. Another try.')+`<div class="two-col"><section class="panel">${storySelect('practice-story','Which story would you like to practise?')}<div class="mode-grid" style="grid-template-columns:1fr 1fr"><button class="mode-card" data-action="begin-practice" data-mode="practice">${icon('chat')}<h2>Practice</h2><p>Feedback after each answer. Scores stay hidden unless you ask.</p>${icon('arrow')}</button><button class="mode-card" data-action="begin-practice" data-mode="test">${icon('target')}<h2>Test</h2><p>Three questions, no hints. See your feedback at the end.</p>${icon('arrow')}</button></div></section><section class="panel"><h2>Keep it human.</h2><ul class="help-list"><li>Say it out loud first, then type or use your keyboard microphone.</li><li>Use “I” for your action and “we” for the team.</li><li>A small, honest outcome is enough.</li></ul><p class="small-muted">Feedback checks your text. It does not analyse voice, accent, pauses or filler words. Local scores are coaching estimates, not a validated assessment or a hiring prediction.</p>${state.profile.target?`<div class="divider"></div><div class="eyebrow">YOUR TARGET</div><p>${e(state.profile.target)}</p>`:''}</section></div>`;
  if(interview.finished)return testResults();
  const idx=interview.index,q=interview.questions[idx],last=interview.last;
  return pageHead(interview.mode==='test'?`TEST · QUESTION ${idx+1} OF 3`:'PRACTICE · ROOM TO TRY AGAIN',interview.mode==='test'?'Take it one question at a time.':'An answer that sounds like you.','Your own words are enough.',button('End session','end-practice','secondary small'))+
    `<div class="two-col"><section><div class="question-card"><div class="eyebrow">YOUR QUESTION</div><h2>${e(q)}</h2><button class="btn light small" style="margin-top:18px" data-action="read-question">${icon('volume')} Read aloud</button></div><form id="answer-form"><div class="field"><label for="practice-answer">Your answer</label><textarea name="answer" id="practice-answer" class="editor" maxlength="10000" required placeholder="Start at the moment that matters…">${e(interview.draft||'')}</textarea><small>Use keyboard dictation to speak your answer. No audio is recorded by this app.</small></div><div class="word-count" id="answer-count">${words(interview.draft||'').length} words</div><label class="check"><input type="checkbox" name="confirmed" required><span>I confirm this answer describes my experience and want to save it with my feedback.</span></label><div class="actions">${button(interview.mode==='test'?(idx===2?'Finish test':'Next question'):(last?'Try this version':'Get feedback'),'submit-answer','','type="submit"')}${interview.mode==='practice'&&last?button('Try another question','next-question','secondary'):''}</div></form></section><aside>${interview.mode==='test'?`<div class="panel"><h2>You’ve got the floor.</h2><p class="subhead">Your answers are held in this session until you finish all three. Feedback comes at the end.</p><p class="small-muted" style="margin-top:22px">${idx} of 3 answers completed</p></div>`:last?feedbackHTML(last,true):`<div class="panel"><h2>A little structure helps.</h2><ol class="help-list"><li>Open with the interesting moment.</li><li>Say what you did and why.</li><li>End with what changed or what you learned.</li></ol><div class="divider"></div><h3>Your story</h3><p class="small-muted">${e(state.stories.find(s=>s.id===interview.storyId)?.title||'')}</p></div>`}</aside></div>`;
}
function feedbackHTML(attempt,showToggle=false){const f=attempt.feedback,show=attempt.mode==='test'||showScores;
  const prior=state.attempts.filter(a=>a.id!==attempt.id&&a.storyId===attempt.storyId&&a.question===attempt.question&&a.feedback.method===f.method&&a.createdAt<=attempt.createdAt).at(-1);
  return `<section class="feedback"><div class="row spaced"><h2>${show?'Your feedback':'Something to build on'}</h2>${showToggle?`<button class="text-link" data-action="toggle-scores">${show?'Hide score':'Show score'}</button>`:''}</div><p class="small-muted" style="margin-top:10px">${f.method==='ai'?'AI coaching feedback':'Local coaching estimate'} · text only · not a validated assessment</p>${show?`<div class="score-total"><b>${f.total}</b><span>/ 100 · ${band(f.total)}</span></div>${prior?`<p class="small-muted">${f.total-prior.feedback.total>=0?'+':''}${f.total-prior.feedback.total} points from your previous answer to this question.</p>`:''}`:''}<h3>What worked</h3><p class="small-muted">${e(f.worked)}</p><div class="callout"><div class="eyebrow">ONE THING TO TRY</div><p>${e(f.fix)}</p></div>${f.rows.map(r=>`<div class="rubric-row"><div class="row spaced"><strong>${e(r.name)}</strong>${show?`<span>${r.score} / 20</span>`:''}</div>${show?`<div class="bar"><div style="width:${r.score*5}%"></div></div>`:''}${r.quote?`<q>${e(r.quote)}</q>`:'<span class="small-muted">No clear evidence in this answer yet.</span>'}</div>`).join('')}<details class="details" style="margin-top:22px"><summary>Your words, in a different order</summary><p class="small-muted">Only sentences from this answer. Keep this order if it helps; add missing detail yourself.</p><p class="pre">${e(f.stronger)}</p></details></section>`;
}
function testResults(){const attempts=interview.pending;const avg=Math.round(attempts.reduce((n,a)=>n+a.feedback.total,0)/3);return pageHead('TEST COMPLETE','Three answers. A clearer next step.','Your results are saved on this device.',button('Back to practice','end-practice','secondary'))+`<div class="panel"><div class="score-total"><b>${avg}</b><span>/ 100 average · ${band(avg)}</span></div><p class="small-muted">A coaching estimate across three questions, not a hiring or readiness guarantee.</p></div>${attempts.map((a,i)=>`<section class="below"><h2>Question ${i+1}</h2><p>${e(a.question)}</p><details class="details"><summary>Your answer</summary><p class="pre">${e(a.answer)}</p></details>${feedbackHTML(a)}</section>`).join('')}`;}
function progressView(){const all=state.attempts,counts=coverage(state.stories),covered=Object.values(counts).filter(Boolean).length,omitted=state.stories.filter(s=>s.omitted).length;
  if(!all.length)return pageHead('LOOK HOW FAR YOU’VE COME','Small moments add up.','Your own evidence, over time.')+`<div class="metrics"><div class="metric"><div class="number">${state.stories.length}</div><div class="label">Confirmed stories</div></div><div class="metric"><div class="number">${covered} / 8</div><div class="label">Skills with evidence</div></div><div class="metric"><div class="number">${omitted}</div><div class="label">Stories you’d have left out</div></div></div>`+empty('The first try is a starting point.','Practise one answer to start a history you can learn from. Your score stays hidden until you ask.',`<a class="btn" href="#practice">Start practising ${icon('arrow')}</a>`);
  const sums=RUBRIC.map((name,i)=>({name,avg:Math.round(all.reduce((n,a)=>n+a.feedback.rows[i].score,0)/all.length)}));
  const weakest=[...sums].sort((a,b)=>a.avg-b.avg)[0],uses=state.stories.map(s=>({s,n:all.filter(a=>a.storyId===s.id).length})).sort((a,b)=>b.n-a.n);
  return pageHead('LOOK HOW FAR YOU’VE COME','Small moments add up.','Look for a direction, not a perfect score.',button(showScores?'Hide scores':'Show scores','toggle-scores','secondary'))+
  `<div class="metrics"><div class="metric"><div class="number">${all.length}</div><div class="label">Answers practised</div></div><div class="metric"><div class="number">${covered} / 8</div><div class="label">Skills with evidence</div></div><div class="metric"><div class="number">${omitted}</div><div class="label">Stories you’d have left out</div></div></div><div class="two-col"><section class="panel"><h2>${showScores?'Your last ten answers':'Every attempt is practice'}</h2>${showScores?`<div class="trend" aria-label="Last ten scores">${all.slice(-10).map((a,i)=>`<div class="trend-col"><span>${a.feedback.total}</span><div class="column" style="height:${a.feedback.total*1.2}px" title="Answer ${i+1}: ${a.feedback.total} out of 100"></div></div>`).join('')}</div><p class="small-muted" style="margin-top:15px">Chronological order. Different questions and coaching methods are not directly comparable.</p>`:`<p class="subhead">You’ve shown up ${all.length} time${all.length===1?'':'s'}. Keep making the answer more specific, and more yours.</p>`}<div class="divider"></div><h3>Worth practising next: ${e(weakest.name)}</h3><p class="small-muted">This part has the lowest average coaching estimate across your answers.</p></section><section class="panel"><h2>How you tell your stories</h2><p class="subhead">${uses[0].n>=3?`You’ve used “${e(uses[0].s.title)}” ${uses[0].n} times. Try another story to broaden your range.`:'Keep a few stories in rotation. Different moments reveal different things about you.'}</p><div class="divider"></div><div class="row spaced"><div><strong>${all.reduce((n,a)=>n+a.feedback.iCount,0)}</strong> × “I”</div><div><strong>${all.reduce((n,a)=>n+a.feedback.weCount,0)}</strong> × “we”</div></div><p class="small-muted" style="margin-top:15px">Neither is wrong. “I” helps make your contribution visible; “we” gives your team credit.</p></section></div><section class="below"><div class="section-head"><h2>Your practice history</h2></div><div class="history-list">${[...all].reverse().map(a=>`<div class="history-item"><div><p>${e(a.question)}</p><small>${new Date(a.createdAt).toLocaleDateString()} · ${e(a.mode)} · ${a.feedback.method==='local'?'Local estimate':'AI feedback'}</small></div><div class="row">${showScores?`<strong>${a.feedback.total}/100</strong>`:''}<button class="text-link" data-action="attempt" data-id="${e(a.id)}">Review</button><button class="round-btn" data-action="delete-attempt" data-id="${e(a.id)}" aria-label="Delete this practice answer">${icon('close')}</button></div></div>`).join('')}</div></section>`;
}
function settingsView(){return pageHead('YOU’RE IN CONTROL','Your space, your rules.','Your stories belong to you.')+`<div class="two-col"><section class="panel"><h2>Private, by default.</h2><p class="subhead">Your profile, stories and practice history live in this browser. There are no accounts, trackers or automatic social posts.</p><p class="small-muted" style="margin-top:18px">Browser storage is not an encrypted vault. Anyone using this browser profile can open your stories. Clearing browser data removes them. Export a backup before changing devices.</p><div class="actions"><a class="btn secondary" href="#profile">Edit profile &amp; CV</a>${button(`${icon('download')} Export my data`,'export','secondary')}${button('Import a backup','import','secondary')}${storageError?button('Download recovery copy','recover','secondary'):''}</div><input id="import-file" type="file" accept="application/json,.json" hidden><div class="divider"></div><h3>Try the sample space</h3><p class="small-muted">Explore fictional stories without changing your own data.</p>${button('Open sample space','demo','secondary small')}</section><section class="panel"><h2>Buddy’s intelligence</h2><p class="subhead">Guided mode works entirely on your device. It asks open questions, arranges your exact words and gives transparent text-based coaching.</p><div class="divider"></div><h3>Optional Gemini assistance</h3><p class="small-muted">${aiAvailable?'A Gemini API key is configured on this local server. Enable it for this session to try the connection.':'Gemini is not configured. Add your Google AI Studio key as GEMINI_API_KEY in the project’s .env file, then restart the server and reload this page.'}</p><p class="small-muted">When enabled, only the current conversation or practice question and answer are sent to Google Gemini via the local server. Your full story bank and CV are not sent. Google’s unpaid-service terms allow submitted content to be used to improve products and reviewed by humans. Use fictional examples for a free-tier demo; do not send sensitive or personal information. Quotas vary by project.</p>${aiAvailable?button(aiConsent?'Turn off AI for this session':'Review & enable Gemini',aiConsent?'disable-ai':'enable-ai','secondary'):''}<p class="small-muted" style="margin-top:16px">Voice uses your device’s speech services. Read-aloud may depend on installed voices. Keyboard dictation is controlled by your operating system.</p></section></div><section class="panel below"><h2>A fresh start</h2><p class="subhead">Erase your profile, stories, drafts and practice history from this browser. Export anything you want to keep first.</p><div class="actions">${button('Delete all my data','delete-all','danger')}</div></section>`;}
function profileView(){const p=state.profile;return pageHead('THE STARTING POINT','Your life has a few chapters.','Give Buddy a few places to look. You can change any of this.')+`<div class="two-col"><section class="panel"><form id="profile-form"><div class="field"><label for="profile-name">Your name</label><input id="profile-name" name="name" value="${e(p.name)}" maxlength="80" required></div><div class="field"><label for="profile-cv">Your existing CV</label><textarea id="profile-cv" name="cv" maxlength="30000" placeholder="Paste your CV, or build one below.">${e(p.cv)}</textarea></div><button class="text-link" type="button" data-action="extract-cues">Suggest starting points from this CV ${icon('arrow')}</button><div class="field" style="margin-top:22px"><label for="profile-experiences">Things Buddy can ask about</label><textarea id="profile-experiences" name="experiences" maxlength="30000" placeholder="One per line: a project, a role, helping at home…">${e(p.experiences.join('\n'))}</textarea><small>These are your cues. Check and edit each one before saving.</small></div><div class="field"><label for="profile-target">What are you aiming for?</label><input id="profile-target" name="target" maxlength="300" value="${e(p.target)}" placeholder="A role, a company, or just exploring"></div><div class="field"><label for="profile-posting">Job posting <span class="muted">Optional</span></label><textarea id="profile-posting" name="posting" maxlength="30000" placeholder="Paste the actual posting here.">${e(p.posting)}</textarea><small>Buddy works from the text you provide. It does not research the company.</small></div><button class="text-link" type="button" data-action="suggest-target-skills">Suggest skills from posting ${icon('spark')}</button>${skillChecks(p.targetSkills,'target-skills',8)}<label class="check"><input type="checkbox" name="confirmed" required><span>I’ve checked this information and want to save it.</span></label>${button('Save profile','submit-profile','','type="submit"')}</form></section><section><div class="panel"><h2>Starting without a CV?</h2><p class="subhead">School, home, work, things you taught yourself. Experience doesn’t need a job title.</p><div class="actions">${button('Build my CV with Buddy','build-cv','secondary')}</div></div><div class="panel below"><div class="section-head"><h2>Your CV draft</h2>${icon('book')}</div><p class="small-muted">A factual starting draft from your profile and confirmed stories. Add your contact details, dates and role titles before using it.</p><textarea id="cv-preview" class="editor" maxlength="30000" aria-label="CV draft">${e(state.profile.cvDraft || cvDraft(state))}</textarea><label class="check" style="margin-top:15px"><input type="checkbox" id="cv-draft-confirm"><span>I have checked this CV draft and confirm its facts.</span></label><div class="actions">${button('Save CV draft','save-cv-draft')}${button(`${icon('download')} Download CV draft`,'download-cv','secondary')}${button('Refresh from stories','refresh-cv','ghost')}</div></div></section></div>`;}
function skillChecks(selected,name='skills',limit=3){return `<fieldset style="margin-top:20px"><legend>${limit===3?'Skills this story shows':'Skills to aim for'} <span class="small-muted">Choose up to ${limit}</span></legend><div class="check-grid">${SKILLS.map(s=>`<label class="check-row"><input type="checkbox" name="${name}" value="${e(s)}" ${selected.includes(s)?'checked':''}>${e(s)}</label>`).join('')}</div></fieldset>`;}
function bindForms(){
  const talkForm=document.querySelector('#talk-form');if(talkForm){talkForm.onsubmit=submitTalk;document.querySelector('#talk-answer').oninput=ev=>talk.draft=ev.target.value;}
  const searchInput=document.querySelector('#story-search');if(searchInput){searchInput.oninput=ev=>{search=ev.target.value;updateResults();};document.querySelector('#skill-filter').onchange=ev=>{filter=ev.target.value;updateResults();};}
  const st=document.querySelector('#studio-text');if(st){st.oninput=ev=>{studio.text=ev.target.value;document.querySelector('#studio-count').textContent=`${words(studio.text).length} words · ~${Math.round(words(studio.text).length/2.4)} seconds spoken`;};document.querySelector('#studio-story').onchange=ev=>changeStudio(ev.target.value,studio.format);}
  const answerForm=document.querySelector('#answer-form');if(answerForm){answerForm.onsubmit=submitAnswer;document.querySelector('#practice-answer').oninput=ev=>{interview.draft=ev.target.value;document.querySelector('#answer-count').textContent=words(ev.target.value).length+' words';};}
  const profile=document.querySelector('#profile-form');if(profile)profile.onsubmit=ev=>{ev.preventDefault();const f=new FormData(profile);try{if(!f.get('name').trim())throw Error('Add a name Buddy can use.');save({...state,profile:{...state.profile,name:f.get('name').trim(),cv:f.get('cv').trim(),target:f.get('target').trim(),posting:f.get('posting').trim(),experiences:f.get('experiences').split('\n').map(x=>x.trim()).filter(Boolean),targetSkills:f.getAll('target-skills')}});toast('Profile saved on this device.');render();}catch(err){toast(err.message);}};
  const importFile=document.querySelector('#import-file');if(importFile)importFile.onchange=importBackup;
}
function updateResults(){const shown=state.stories.filter(s=>(!filter||s.skills.includes(filter))&&[s.title,s.moment,s.value,s.source].join(' ').toLowerCase().includes(search.toLowerCase()));document.querySelector('#story-results').innerHTML=bankResults(shown);}
function download(filename,text,type='text/plain'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
document.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(!el)return;const a=el.dataset.action;try{
  if(a==='close-modal')modal.close();
  else if(a==='start')state.profile.name?goto('buddy'):onboarding();
  else if(a==='demo'){demo=true;aiConsent=false;showScores=false;state=sampleState();talk=null;interview=null;goto('home');render();}
  else if(a==='exit-demo'){demo=false;aiConsent=false;showScores=false;state=raw?validateState(JSON.parse(raw)):freshState();talk=null;interview=null;studio={storyId:'',format:'interview',text:''};goto('home');render();}
  else if(a==='export')download('your-story-backup.json',JSON.stringify(state,null,2),'application/json');
  else handleAction(a,el);
}catch(err){toast(err.message);}});
function handleAction(a,el){
  const id=el.dataset.id;
  if(a==='explore')chooseCue();
  else if(a==='gap'){startTalk('gap','An experience you haven’t explored',gapQuestion(nextGap(state)));}
  else if(a==='cue')startTalk('explore',el.dataset.cue);
  else if(a==='build-cv')buildCV();
  else if(a==='end-talk')confirmAction('End this conversation?','This conversation has not been saved. You can keep talking or discard it.',()=>{talk=null;modal.close();render();},'Discard conversation');
  else if(a==='back-talk'){talk.draft=talk.answers.pop();talk.questions=talk.questions.slice(0,talk.answers.length+1);render();}
  else if(a==='review-talk')editStory(storyFromConversation(talk.cue,talk.answers),true);
  else if(a==='new-story')editStory({id:uid(),title:'',context:'',moment:'',action:'',result:'',value:'',skills:[],omitted:false,confirmed:false,createdAt:new Date().toISOString(),source:'My experience',notes:''},true);
  else if(a==='story')showStory(id);
  else if(a==='edit-story')editStory(state.stories.find(s=>s.id===id));
  else if(a==='delete-story')confirmAction('Delete this story?','This also removes drafts and practice answers linked to it. Export a backup first if you want to keep them.',()=>{save(deleteStory(state,id));if(interview?.storyId===id)interview=null;modal.close();render();toast('Story and linked records deleted.');},'Delete story');
  else if(a==='use-story'){studio={storyId:id,format:'interview',text:draftStory(state.stories.find(s=>s.id===id),'interview')};modal.close();goto('studio');}
  else if(a==='practice-story'){modal.close();beginInterview('practice',id);}
  else if(a==='thread')showThread();
  else if(a==='skill'){filter=el.dataset.skill;search='';goto('bank');}
  else if(a==='clear-filters'){filter='';search='';render();}
  else if(a==='format')changeStudio(studio.storyId,el.dataset.format);
  else if(a==='save-draft'){if(!document.querySelector('#draft-confirm').checked)throw Error('Check the draft and confirm its facts before saving.');if(!studio.text.trim())throw Error('Write a draft first.');save({...state,drafts:[...state.drafts,{id:uid(),storyId:studio.storyId,format:studio.format,text:studio.text,createdAt:new Date().toISOString()}]});render();toast('Draft saved. Nothing was posted.');}
  else if(a==='download-draft')download(`your-story-${studio.format}.txt`,studio.text);
  else if(a==='copy-draft')navigator.clipboard.writeText(studio.text).then(()=>toast('Draft copied.')).catch(()=>toast('Clipboard is unavailable. Select the draft and copy it, or download it.'));
  else if(a==='load-draft'){const d=state.drafts.find(x=>x.id===id);changeStudio(d.storyId,d.format,d.text);}
  else if(a==='delete-draft')confirmAction('Delete this saved draft?','Your source story will remain.',()=>{save({...state,drafts:state.drafts.filter(d=>d.id!==id)});modal.close();render();},'Delete draft');
  else if(a==='studio-practice')beginInterview('practice',studio.storyId);
  else if(a==='begin-practice')beginInterview(el.dataset.mode,document.querySelector('#practice-story').value);
  else if(a==='end-practice'){if(interview?.mode==='test'&&!interview.finished)confirmAction('Leave this test?','The unfinished test answers will be discarded.',()=>{interview=null;modal.close();render();},'Leave test');else{interview=null;render();}}
  else if(a==='toggle-scores'){showScores=!showScores;render();}
  else if(a==='next-question'){interview.index=(interview.index+1)%3;interview.last=null;interview.draft='';render();}
  else if(a==='attempt'){const attempt=state.attempts.find(x=>x.id===id);openModal('Your practice answer',`<p>${e(attempt.question)}</p><details class="details"><summary>Read your answer</summary><p class="pre">${e(attempt.answer)}</p></details>${feedbackHTML(attempt)}`);}
  else if(a==='delete-attempt')confirmAction('Delete this practice answer?','Its answer, score and feedback will be removed from your history.',()=>{save({...state,attempts:state.attempts.filter(x=>x.id!==id)});interview=null;modal.close();render();},'Delete answer');
  else if(a==='read-question')readAloud(view==='buddy'?talk.questions[talk.answers.length]:interview.questions[interview.index]);
  else if(a==='extract-cues'){const cv=document.querySelector('#profile-cv').value;const cues=extractExperiences(cv);document.querySelector('#profile-experiences').value=cues.join('\n');toast(cues.length?'Starting points suggested from CV lines. Check and edit before saving.':'No clear lines found. Add a few starting points in your own words.');}
  else if(a==='suggest-target-skills'){const skills=suggestSkills(document.querySelector('#profile-posting').value);document.querySelectorAll('[name="target-skills"]').forEach(x=>x.checked=skills.includes(x.value));toast('Keyword-based suggestions. Adjust them to match the posting.');}
  else if(a==='download-cv')download('your-story-cv-draft.txt',document.querySelector('#cv-preview').value);
  else if(a==='save-cv-draft'){if(!document.querySelector('#cv-draft-confirm').checked)throw Error('Confirm the facts before saving your CV draft.');save({...state,profile:{...state.profile,cvDraft:document.querySelector('#cv-preview').value}});toast('CV draft saved.');}
  else if(a==='refresh-cv')confirmAction('Replace this CV draft?', 'This replaces the text in the editor with your current profile and story facts. Your saved draft stays unchanged until you save again.',()=>{document.querySelector('#cv-preview').value=cvDraft(state);modal.close();},'Refresh draft');
  else if(a==='import')document.querySelector('#import-file').click();
  else if(a==='recover')download('your-story-recovery.txt',localStorage.getItem(KEY)||'No stored data');
  else if(a==='delete-all')confirmAction('Delete everything on this device?','This removes your profile, stories, drafts and practice history. This cannot be undone without an exported backup.',()=>{if(!demo){localStorage.removeItem(KEY);raw=null;storageError='';}state=freshState();talk=null;interview=null;studio={storyId:'',format:'interview',text:''};aiConsent=false;modal.close();goto('home');render();toast(demo?'Sample space cleared. Your data is unchanged.':'All Your Story data removed from this browser.');},'Delete all data');
  else if(a==='enable-ai')confirmAction('Enable Gemini for this session?','Your current conversation answers, or your practice question and answer, will be sent to Google Gemini through this local server. Your full CV and story bank stay here. Google may use free-tier input and output to improve products, and human reviewers may see them. Use fictional demo content, not personal or sensitive information. AI feedback can be wrong. Nothing is sent until you continue a conversation or submit an answer.',()=>{aiConsent=true;modal.close();render();toast('AI enabled for this session only.');},'Enable AI');
  else if(a==='disable-ai'){aiConsent=false;render();toast('AI disabled. Guided mode is active.');}
}
function confirmAction(title,body,fn,label='Continue'){openModal(title,`<p>${body}</p><div class="dialog-foot">${button('Cancel','close-modal','secondary')}<button id="confirm-action" class="btn ${label.startsWith('Delete')?'danger':''}">${label}</button></div>`);document.querySelector('#confirm-action').onclick=()=>{try{fn();}catch(err){toast(err.message);}};}
function chooseCue(){
  const cues=state.profile.experiences.length?state.profile.experiences:extractExperiences(state.profile.cv);
  openModal('Pick a place to begin.',`<p class="small-muted">${cues.length?'These starting points come from your profile. Choose one that feels real to you.':'A small part of your life is enough. It doesn’t need a title.'}</p><div class="saved-list">${cues.slice(0,12).map(c=>`<button data-action="cue" data-cue="${e(c)}">${e(c)} ${icon('arrow')}</button>`).join('')}</div><form id="cue-form"><div class="field"><label for="custom-cue">${cues.length?'Or choose another experience':'Something you’ve been part of'}</label><input id="custom-cue" name="cue" maxlength="300" required placeholder="A group project, a shift, helping at home…"></div><div class="actions">${button('Start here','submit-cue','','type="submit"')}</div></form>`);
  document.querySelector('#cue-form').onsubmit=ev=>{ev.preventDefault();const cue=new FormData(ev.target).get('cue').trim();if(!cue)return;startTalk('explore',cue);};
}
function startTalk(mode,cue,first){talk={mode,cue,answers:[],questions:[first||question(0,cue)],draft:''};modal.close();goto('buddy');render();}
async function submitTalk(ev){ev.preventDefault();const answer=new FormData(ev.target).get('answer').trim();if(!answer)return;const active=talk;const submit=ev.target.querySelector('[type=submit]');submit.disabled=true;
  active.answers.push(answer);active.draft='';const stage=active.answers.length;
  if(stage<7){let q=question(stage,active.cue,stage===1?answer:'');if(aiConsent){try{const result=await callAI('question',{stage,cue:active.cue,answers:active.answers});if(talk!==active)return;q=result.question;}catch(err){toast(err.message+' Guided mode will continue.');}}active.questions.push(q);}
  if(talk!==active)return;render();document.querySelector('#talk-answer')?.focus({preventScroll:true});document.querySelector('#current-question')?.scrollIntoView({behavior:'auto',block:'center'});
  if(stage===7)editStory(storyFromConversation(active.cue,active.answers),true);
}
function editStory(s,isNew=false){if(!s)throw Error('Story not found.');openModal(isNew?'Make this story yours.':'Your story, in your words.',`<form id="story-form"><div class="field"><label for="story-title">A title for this moment</label><input id="story-title" name="title" maxlength="160" value="${e(s.title)}" required></div><div class="form-grid">${[['moment','The interesting moment',true],['context','A little context',false],['action','What I personally did',true],['result','What happened next',false],['value','Why it mattered to me',true]].map(([k,label,required])=>`<div class="field ${k==='value'?'wide':''}"><label for="story-${k}">${label}${required?'':' <span class="muted">Optional</span>'}</label><textarea id="story-${k}" name="${k}" maxlength="5000" ${required?'required':''}>${e(s[k])}</textarea></div>`).join('')}</div><div class="field"><label for="story-source">Where this story comes from</label><input id="story-source" name="source" maxlength="300" value="${e(s.source)}"></div>${skillChecks(s.skills)}<p class="small-muted">Suggested tags are only starting points. Choose what this experience really shows.</p><label class="check"><input type="checkbox" name="omitted" ${s.omitted?'checked':''}><span>I would have left this story out of an application.</span></label><label class="check"><input type="checkbox" name="confirmed" required><span>I confirm this happened. These are my actions, and these words reflect my experience.</span></label>${s.notes?`<details class="details"><summary>Review the words this came from</summary><div class="field"><label for="story-notes">Confirmed conversation notes</label><textarea id="story-notes" name="notes" maxlength="20000">${e(s.notes)}</textarea></div></details>`:''}<div class="dialog-foot">${button('Cancel','close-modal','secondary')}${button(isNew?'Save my story':'Save changes','submit-story','','type="submit"')}</div></form>`,'Nothing is kept until you confirm it. Missing outcomes can stay blank.');
  document.querySelector('#story-form').onsubmit=ev=>{ev.preventDefault();const f=new FormData(ev.target);try{const updated={...s,...Object.fromEntries(['title','moment','context','action','result','value','source'].map(k=>[k,f.get(k).trim()])),notes:f.has('notes')?f.get('notes').trim():s.notes,skills:f.getAll('skills'),omitted:f.has('omitted'),confirmed:f.has('confirmed')};validateStory(updated);save({...state,stories:isNew?[updated,...state.stories]:state.stories.map(x=>x.id===s.id?updated:x)});if(isNew)talk=null;modal.close();filter='';search='';goto('bank');render();toast('Story saved. Every word is yours to change.');}catch(err){toast(err.message);}};
}
function showStory(id){const s=state.stories.find(x=>x.id===id);if(!s)return;openModal(e(s.title),`${facts(s)}<div class="tags">${s.skills.map(x=>`<span class="tag">${e(x)}</span>`).join('')}</div>${s.omitted?'<p class="small-muted">You would have left this one out. It belongs here.</p>':''}<div class="actions">${button('Use this story','use-story','',`data-id="${e(id)}"`)}${button('Practise','practice-story','secondary',`data-id="${e(id)}"`)}${button('Edit','edit-story','secondary',`data-id="${e(id)}"`)}${button('Delete','delete-story','ghost',`data-id="${e(id)}"`)}</div>`,'Confirmed by you · '+new Date(s.createdAt).toLocaleDateString());}
function showThread(){const thread=findThread(state.stories);if(!thread){openModal('One story is a moment.',`<p>A few reveal a pattern. Save at least two stories, then look at what you said mattered in each.</p><p class="small-muted">Buddy offers a starting point. You decide what connects them.</p>`);return;}openModal(e(thread.title),`<p>${e(thread.text)}</p>${thread.quotes.map(q=>`<section class="thread"><div class="eyebrow">${e(q.title)}</div><blockquote>${e(q.value)}</blockquote></section>`).join('')}<p class="small-muted" style="margin-top:20px">This is a reflection prompt based on your words, not a personality assessment.</p>`);}
function buildCV(){
  openModal('Experience doesn’t need a title.',`<p>What have you done in these parts of your life? Skip anything that doesn’t fit. One specific activity per line is enough.</p><form id="cv-build-form">${AREAS.map((a,i)=>`<div class="field"><label for="area-${i}">${e(a)}</label><textarea id="area-${i}" name="area-${i}" maxlength="1200" placeholder="An activity, a responsibility, something you learned…" style="min-height:75px"></textarea></div>`).join('')}<label class="check"><input type="checkbox" name="confirmed" required><span>These experiences are mine. Save them as starting points for my CV.</span></label><div class="dialog-foot">${button('Save & explore a moment','submit-cv-build','','type="submit"')}</div></form>`,'We’ll keep your own words, then find a story inside them.');
  document.querySelector('#cv-build-form').onsubmit=ev=>{ev.preventDefault();const f=new FormData(ev.target);const entries=AREAS.flatMap((a,i)=>f.get(`area-${i}`).split('\n').map(x=>x.trim()).filter(Boolean).map(x=>`${a}: ${x}`));try{if(!entries.length)throw Error('Add at least one experience, or close this and explore with Buddy.');save({...state,profile:{...state.profile,experiences:[...new Set([...state.profile.experiences,...entries])]}});modal.close();chooseCue();toast('Your CV starting points are saved. Let’s find the first story.');}catch(err){toast(err.message);}};
}
function changeStudio(id,format,text){const next=()=>{studio={storyId:id,format,text:text??draftStory(state.stories.find(s=>s.id===id),format)};modal.close();render();};const s=state.stories.find(x=>x.id===studio.storyId);const isSaved=state.drafts.some(d=>d.text===studio.text&&d.storyId===studio.storyId);if(s&&studio.text!==draftStory(s,studio.format)&&!isSaved)confirmAction('Replace this unsaved draft?','Save or copy your edits first if you want to keep them.',next,'Replace draft');else next();}
function beginInterview(mode,id){showScores=false;if(!state.stories.some(s=>s.id===id))throw Error('Choose a confirmed story first.');interview={mode,storyId:id,sessionId:uid(),questions:interviewQuestions(state,state.stories.find(s=>s.id===id)),index:0,pending:[],draft:'',last:null,finished:false};goto('practice');render();}
async function submitAnswer(ev){
  ev.preventDefault();const answer=new FormData(ev.target).get('answer')||document.querySelector('#practice-answer').value;const text=answer.trim();if(!text)return;
  const active=interview,btn=ev.target.querySelector('[type=submit]');btn.disabled=true;btn.textContent=active.mode==='test'?'Saving answer…':'Reading your answer…';
  try{
    let f=scoreAnswer(text,active.questions[active.index],state.stories.find(s=>s.id===active.storyId));
    if(aiConsent){try{const remote=await callAI('feedback',{answer:text,question:active.questions[active.index]});f={...f,...remote,method:'ai'};}catch(err){toast(err.message+' Using the local coaching estimate.');}}
    if(interview!==active)return;
    const attempt={id:uid(),storyId:active.storyId,sessionId:active.sessionId,question:active.questions[active.index],answer:text,mode:active.mode,createdAt:new Date().toISOString(),confirmed:true,feedback:f};
    if(active.mode==='practice'){save({...state,attempts:[...state.attempts,attempt]});active.last=attempt;}
    else {const pending=[...active.pending,attempt];if(active.index===2){save({...state,attempts:[...state.attempts,...pending]});active.pending=pending;active.finished=true;}else{active.pending=pending;active.index++;active.draft='';}}
    render();if(active.mode==='practice')document.querySelector('.feedback')?.scrollIntoView({block:'start',behavior:'auto'});
  }catch(err){toast(err.message);btn.disabled=false;btn.textContent=active.mode==='test'?'Continue test':'Get feedback';}
}
async function importBackup(ev){const file=ev.target.files[0];if(!file)return;try{if(file.size>5000000)throw Error('Backup is too large. The limit is 5 MB.');const imported=validateState(JSON.parse(await file.text()));confirmAction('Replace this device’s story bank?',`This backup has ${imported.stories.length} stories and ${imported.attempts.length} practice answers. Export your current data first if you want to keep it.`,()=>{save(imported);talk=null;interview=null;studio={storyId:'',format:'interview',text:''};modal.close();goto('home');render();toast('Backup restored.');},'Replace my data');}catch(err){toast('Import stopped: '+err.message);}finally{ev.target.value='';}}
function readAloud(text){if(!('speechSynthesis' in window)){toast('Read-aloud isn’t available in this browser. Your question is shown on screen.');return;}speechSynthesis.cancel();const speech=new SpeechSynthesisUtterance(text);speech.lang='en-US';speech.rate=.92;speech.onerror=()=>toast('Read-aloud is unavailable. You can read the question on screen.');speechSynthesis.speak(speech);}
async function callAI(task,payload){const response=await fetch('/api/coach',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({task,payload,consent:true}),signal:AbortSignal.timeout(25000)});if(!response.ok){const failure=await response.json().catch(()=>({}));throw Error(failure.error||(response.status===429?'Gemini quota reached. Try again later.':response.status===503?'Gemini is not configured.':'Gemini couldn’t respond.'));}return await response.json();}
window.addEventListener('hashchange',()=>{render();document.querySelector('#main').focus({preventScroll:true});window.scrollTo(0,0);});
window.addEventListener('storage',event=>{if(event.key===KEY&&!demo)toast('Your stories changed in another tab. Reload before editing. Copy unsaved text first.');});
render();
if(['127.0.0.1','localhost'].includes(location.hostname))fetch('/api/config').then(r=>r.ok?r.json():null).then(c=>{aiAvailable=c?.ai===true;if(view==='settings')render();}).catch(()=>{});
window.addEventListener('beforeunload',event=>{if(talk?.answers.length || (interview?.mode==='test'&&!interview.finished&&interview.pending.length)){event.preventDefault();event.returnValue='';}});
// Navigation only: agent tools never confirm, save, export or erase a student's facts.
if(document.modelContext?.registerTool){
  try{Promise.resolve(document.modelContext.registerTool({name:'open_story_workspace',description:'Navigate to a Your Story workspace view. Does not save or confirm any information.',inputSchema:{type:'object',properties:{view:{type:'string',enum:nav.map(x=>x[0])}},required:['view'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||Object.keys(input).length!==1||!nav.some(n=>n[0]===input.view))throw Error('Choose a supported workspace view.');location.hash=input.view;render();return {view:input.view};}})).catch(()=>{});}catch{}
}

